def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find full-width uniform separator rows and full-height uniform separator columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def spans(n, seps):
        out, start = [], 0
        for s in seps:
            if s > start:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # Choose the tile containing the most non-background cells as the pattern.
    tiles = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    anchor = max(tiles, key=lambda t: sum(
        grid[r][c] != bg for r in range(t[0], t[1]) for c in range(t[2], t[3])
    ))
    ar0, ar1, ac0, ac1 = anchor
    out = [row[:] for row in grid]
    for r0, r1 in rs:
        for c0, c1 in cs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[ar0 + (r-r0) % (ar1-ar0)][ac0 + (c-c0) % (ac1-ac0)]
    return out
